When clicking outside of AdaptiveAlertDialog, the iOS app crashes. But it works well, when using buttons.
Here the code to reproduce:
```
var showDialog by remember {
        mutableListOf(false)
    }

// Button to trigger the dialog

// Show the dialog when state is true
    if (showDialog) {
        AdaptiveAlertDialog(
            onConfirm = {
                // Handle confirmation
                showDialog = false
            },
            onDismiss = {
                // Handle dismissal
                showDialog = false
            },
            confirmText = "OK",
            dismissText = "Cancel",
            title = "Alert Dialog",
            text = "This is a native alert dialog from Calf",
            // Optional: Customize iOS dialog style
            iosDialogStyle = AlertDialogIosStyle.Alert, // or ActionSheet
            iosConfirmButtonStyle = AlertDialogIosActionStyle.Default,
            iosDismissButtonStyle = AlertDialogIosActionStyle.Destructive,
        )
    }

    Box(modifier = Modifier.fillMaxSize()) {
        Button(
            onClick = { showDialog = true },
        ) {
            Text("Show Alert Dialog")
        }
    }
```
Any solution?
Thanks.
